SETUP_TRANSLATIONS:dict[str,str]={'window':'Configuration initiale','welcome':'Bienvenue','welcome_text':'Cet assistant configure l’apparence, la mise à l’échelle de l’écran et un premier profil de refroidissement. Tous les réglages restent ''modifiables ensuite.','design':'Design','appearance':'Apparence','light':'Clair (par défaut)','dark':'Sombre','system':'Mode système','accent':'Couleur d’accent','background':'Arrière-plan animé','display':'Écran et mise à l’échelle','auto_scale':'Adapter automatiquement à l’écran et au format','app_scale':'Échelle de l’application','layout':'Disposition','layout_auto':'Automatique','layout_compact':'Compact · 16:10','layout_standard':'Standard · 16:9','layout_ultra':'Ultrawide · 21:9','layout_super':'Super ultrawide · 32:9','system_check':'Vérification du système','deps_ok':'Toutes les dépendances sont installées.','deps_missing':'Paquets manquants : {packages}. Ils pourront être installés plus tard dans Paramètres.','detect_after':'Kraken et les contrôleurs RGB seront détectés après la fin de l’assistant.','starter':'Profil de départ','cooling_profile':'Profil de refroidissement','quiet':'Silencieux · 45% / 35%','balanced':'Équilibré · 55% / 50%','performance':'Performance · 100% / 100%','safe':'Sûr · 65% / 65%','profile_note':'Le profil est appliqué après la détection réussie du périphérique.','finish':'Prêt','finish_text':'L’application démarre en mode clair par défaut. Tous les choix peuvent être modifiés plus tard.','open_help':'Ouvrir l’aide et le guide de démarrage après la configuration','back':'Retour','next':'Suivant','finish_button':'Terminer','cancel':'Annuler'}
HELP_TOPICS:dict[str,dict[str,object]]={'getting_started':{'title':'Premiers pas','intro':'Les principaux espaces d’Open Hardware Control en quelques minutes.','steps':('Choisissez à gauche l’appareil ou l’espace système voulu.','Utilisez les profils pour enregistrer plusieurs réglages ensemble.','Les changements matériels ne sont transmis qu’avec l’action Appliquer/Démarrer correspondante.','Ouvrez le journal si quelque chose ne répond pas.'),'page':0},'lcd':{'title':'Modifier le LCD','intro':'Images, GIF, horloge et données matérielles sont gérés dans l’espace LCD NZXT.','steps':('Ouvrez Appareils → NZXT Kraken → LCD.','Choisissez un contenu fixe ou animé et importez votre image ou GIF si nécessaire.','Les données matérielles peuvent afficher CPU, GPU et liquide avec des designs animés.','Luminosité et orientation se trouvent dans les réglages d’affichage.','Pendant un GIF, OHC coordonne automatiquement les courtes prises USB.'),'page':3},'cooling':{'title':'Refroidissement et profils','intro':'La pompe et les ventilateurs du radiateur Kraken peuvent être fixes ou pilotés par température.','steps':('Ouvrez Appareils → NZXT Kraken → Refroidissement.','Utilisez Silencieux, Équilibré, Performance ou Sûr comme point de départ.','Les courbes peuvent utiliser la température CPU tandis que le liquide reste surveillé pour la sécurité.','Surveillez températures et RPM avant des valeurs très faibles.'),'page':1},'rgb':{'title':'RGB Studio','intro':'RGB Studio regroupe les appareils NZXT et OpenRGB gérés par OHC.','steps':('Détectez et nommez d’abord les appareils.','Testez les zones LED et enregistrez leur nombre.','Sélectionnez des appareils ou groupes puis démarrez un design OHC.','Si une autre fenêtre OpenRGB possède le matériel, OHC attend une remise sûre.'),'page':2},'profiles':{'title':'Profils, import et sauvegarde','intro':'Les profils enregistrent ensemble refroidissement, LCD, RGB et apparence.','steps':('Ouvrez Système → Profils.','Créez vos profils et dupliquez-les avant de grands changements.','Les profils LCD importés affichent un aperçu et les éléments non pris en charge avant activation.','Utilisez Exporter ou Sauvegarde avant de modifier des profils complexes.'),'page':5},'openlinkhub':{'title':'Corsair et OpenLinkHub','intro':'Les appareils Corsair sont intégrés via une instance locale OpenLinkHub.','steps':('Ouvrez Appareils → Corsair · OpenLinkHub.','Vérifiez d’abord le contexte du service, l’API et les appareils détectés.','OHC ne modifie jamais automatiquement un service système tiers.','En cas de doute comparez les valeurs avec la page d’appareil OpenLinkHub.'),'page':8},'settings':{'title':'Paramètres, langue et démarrage','intro':'Configurez ici apparence, langue, écran, dépendances et comportement au démarrage.','steps':('Ouvrez Système → Paramètres.','L’interface peut passer à tout moment entre allemand, anglais, espagnol et français.','Au démarrage du bureau OHC peut rester entièrement minimisé dans la zone de notification.','Les appareils/modules non détectés peuvent être affichés pour le diagnostic.'),'page':4},'troubleshooting':{'title':'Dépannage et journal','intro':'Le journal est la meilleure base de diagnostic commune pour les problèmes matériels.','steps':('Ouvrez Diagnostic → Journal et reproduisez le problème une fois.','Utilisez Tout copier pour joindre la session à un rapport.','Pour les problèmes USB vérifiez les permissions dans Paramètres.','Pour RGB actualisez d’abord la détection OHC avant de lancer d’autres applications RGB.'),'page':7},'supported_devices':{'title':'Appareils pris en charge','intro':'OHC distingue les profils fixes du matériel signalé dynamiquement par les services locaux.','steps':('NZXT Kraken : Kraken 2023 (1e71:300e), Kraken Elite 2024 RGB (3012) et Kraken Plus (3014) sont pris en charge dans le ''registre.','Kraken 2023 Elite (300c) est uniquement détecté en sécurité ; les écritures restent bloquées à cause de l’état connu du ''pilote.','Le NZXT 2023 RGB Controller (2012) est piloté via liquidctl.','Thermalright Levita Vision 360 ARGB Black : écran 1600×720 via TRCC Linux ; pompe/ventilateurs via des canaux hwmon ''confirmés.','Les autres appareils RGB et Corsair suivent les listes dynamiques des versions OpenRGB et OpenLinkHub installées.','Les ventilateurs carte mère/boîtier exigent un PWM hwmon compatible et une confirmation physique ; les ventilateurs GPU ne ''sont jamais modifiés.'),'page':6},'wallpaper_engine':{'title':'Wallpaper Engine','intro':'Un assistant réutilisable explique Steam, Workshop et le module Plasma CaptSilver installé localement.','steps':('Installez Wallpaper Engine via Steam et abonnez-vous d’abord à cinq fonds Workshop.','Sous Fedora, OHC peut vérifier le SHA256 publié puis installer le RPM officiel via Polkit/DNF après deux confirmations ; OHC ''ne reçoit pas le mot de passe.','Choisissez comme bibliothèque Steam le dossier contenant steamapps et utilisez un petit dossier séparé pour vos vidéos.','Sélectionnez les fonds ou vidéos dans OHC ; les options avancées restent dans l’interface Plasma originale.','L’état original est la valeur par défaut et l’optimisation facultative est réversible.'),'page':9},'desktop':{'title':'Designs du bureau','intro':'Les designs expérimentaux modifient certains éléments KDE avec sauvegarde et retour arrière.','steps':('Activez l’espace expérimental dans Paramètres.','Vérifiez les changements prévus avant application.','OHC crée une sauvegarde avant modification et propose une restauration.'),'page':10}}
